const rawOutput = $json.output || "";
const queries = rawOutput
  .split("\n")
  .map(q => q.trim())
  .filter(q => q.length > 0)
  .filter(q => !/^[-*•]?\s*\d*\.?\s*(user safety|safe|unsafe)/i.test(q));

const uniqueQueries = [...new Set(queries)];

return uniqueQueries.map(query => ({
  json: {
    query
  }
}));

