Post URL:
{{ $json.post_url }}

Title:
{{ $json.title }}

Snippet:
{{ $json.snippet }}

parameters.jsCode:
const inputData = $input.all();

return inputData.map(item => {

  const rawOutput = item.json.output;

  let lead;

  if (typeof rawOutput === 'string') {
    lead = JSON.parse(rawOutput);
  } else {
    lead = rawOutput;
  }

  return {
    json: {
      is_lead: lead.is_lead ?? false,
      Person: lead.person_name ?? "",
      Company: lead.company_name ?? "",
      "Lead Type": lead.lead_type ?? "",
      Requirement: lead.requirement ?? "",
      Technology: lead.technology ?? "",
      "LinkedIn Post": lead.post_url ?? "",
      Relevance: lead.relevance ?? "",
      Reason: lead.reason ?? ""
    }
  };
});

const inputData = $input.all();

const posts = [];
const seenUrls = new Set();

for (const item of inputData) {

    const results = item.json.organic_results || [];

    for (const result of results) {

        const url = result.link || "";

        // We only want public LinkedIn posts
        if (!url.includes("linkedin.com/posts/"))
        {
            continue;
        }

        const cleanUrl = url
            .split("?")[0]
            .replace(/\/$/, "");

        // Remove duplicate posts
        if (seenUrls.has(cleanUrl)) {
            continue;
        }

        seenUrls.add(cleanUrl);

        posts.push({
            json: {
                post_url: cleanUrl,
                title: result.title || "",
                snippet: result.snippet || "",
                search_position: result.position || null,
                source: "SerpAPI"
            }
        });
    }
}

return posts;
